const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Amistad Reservoir geometry
  const reservoir = ee.Geometry.Point([-101.05, 29.48]).buffer(15000);

  // 2. Date ranges
  const date2016Start = '2016-08-01';
  const date2016End = '2016-08-31';
  const date2024Start = '2024-08-01';
  const date2024End = '2024-08-31';

  // 3. Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudMask = qa.bitwiseAnd(1024).eq(0).and(qa.bitwiseAnd(2048).eq(0));
    return image.updateMask(cloudMask);
  }

  // 4. Water detection function using MNDWI
  function addWater(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('water');
    const waterMask = mndwi.gt(0);
    return waterMask;
  }

  // 5. Load Sentinel-2 collections
  let col2016 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(reservoir)
    .filterDate(date2016Start, date2016End)
    .map(maskClouds);

  let col2024 = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(reservoir)
    .filterDate(date2024Start, date2024End)
    .map(maskClouds);

  const size2016 = col2016.size().getInfo();
  const size2024 = col2024.size().getInfo();

  console.log(`2016 Images: ${size2016}`);
  console.log(`2024 Images: ${size2024}`);

  if (size2016 === 0 || size2024 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Create water masks and calculate extent
  const water2016 = col2016.map(addWater).median();
  const water2024 = col2024.map(addWater).median();

  // 7. Calculate water area in square meters
  const stats2016 = water2016.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2024 = water2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const count2016 = water2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const count2024 = water2024.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const pixels2016 = count2016.get('water').getInfo();
  const pixels2024 = count2024.get('water').getInfo();

  console.log(`2016 Valid pixels: ${pixels2016}`);
  console.log(`2024 Valid pixels: ${pixels2024}`);

  if (pixels2016 === 0 || pixels2024 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  const waterArea2016 = stats2016.get('water').getInfo();
  const waterArea2024 = stats2024.get('water').getInfo();

  console.log(`2016 Water pixels: ${waterArea2016}`);
  console.log(`2024 Water pixels: ${waterArea2024}`);

  if (waterArea2016 === null || waterArea2024 === null || 
      waterArea2016 === undefined || waterArea2024 === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  const pixelArea = 3000 * 3000;
  const area2016km2 = (waterArea2016 * pixelArea) / 1e6;
  const area2024km2 = (waterArea2024 * pixelArea) / 1e6;

  console.log(`2016 Water area: ${area2016km2.toFixed(2)} km²`);
  console.log(`2024 Water area: ${area2024km2.toFixed(2)} km²`);
  console.log(`Change: ${((area2024km2 - area2016km2) / area2016km2 * 100).toFixed(1)}%`);

  if (waterArea2024 < waterArea2016) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
